static void clientread(Conn*c){char buf[32768];size_t cap=incap();while(c->in.size()<cap){ssize_t n=recv(c->fd,buf,min(sizeof(buf),cap-c->in.size()),0);if(n>0){if(c->in.empty()&&!c->first)c->first=nowms();c->idle=nowms()+cfg.idle;c->in.append(buf,n);if(c->uploading&&!c->waiting)consume_upload(c);if((size_t)n<sizeof(buf))break;}else if(n==0){c->eof=true;break;}else if(errno==EINTR)continue;else if(errno==EAGAIN||errno==EWOULDBLOCK)break;else{destroy(c);return;}}process(c);if(c->eof&&c->uploading&&!c->waiting){destroy(c);return;}if(c->eof&&c->out.empty()&&!c->waiting&&!c->uploading){destroy(c);return;}refresh(c);}
