int main(int argc,char**argv){signal(SIGPIPE,SIG_IGN);if(argc!=3||string(argv[1])!="--config"||!config(argv[2]))return 1;listener=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(listener<0)return 1;int one=1;setsockopt(listener,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));if(bind(listener,(sockaddr*)&cfg.la,sizeof(cfg.la))||listen(listener,4096))return 1;ep=epoll_create1(EPOLL_CLOEXEC);if(ep<0)return 1;add(listener,EPOLLIN);epoll_event events[512];long long nextscan=nowms()+10;while(true){int n=epoll_wait(ep,events,512,10);if(n<0){if(errno==EINTR)continue;break;}for(int i=0;i<n;i++){int fd=events[i].data.fd;uint32_t ev=events[i].events;if(fd==listener){for(;;){int s=accept4(listener,nullptr,nullptr,SOCK_NONBLOCK|SOCK_CLOEXEC);if(s<0){if(errno==EINTR)continue;break;}if(clients.size()>=cfg.maxconn){::close(s);continue;}Conn*c=new Conn;c->fd=s;c->idle=nowms()+cfg.idle;clients[s]=c;add(s,EPOLLIN|EPOLLRDHUP);}continue;}auto ui=ups.find(fd);if(ui!=ups.end()){upstream(ui->second,ev);continue;}auto it=clients.find(fd);if(it==clients.end())continue;Conn*c=it->second;if((ev&EPOLLHUP)&&c->waiting){destroy(c);continue;}if(ev&(EPOLLIN|EPOLLRDHUP|EPOLLHUP|EPOLLERR)){clientread(c);if(!clients.count(fd))continue;c=clients[fd];}if(ev&EPOLLOUT)clientwrite(c);}long long t=nowms();if(t<nextscan)continue;nextscan=t+10;vector<int> ids;ids.reserve(clients.size());for(auto&x:clients)ids.push_back(x.first);for(int fd:ids){auto it=clients.find(fd);if(it==clients.end())continue;Conn*c=it->second;if(c->uploading&&!c->waiting&&t>=c->bodydeadline){error(c,408,true);refresh(c);}else if(c->waiting&&t>=c->updeadline){error(c,502,false);refresh(c);}else if(!c->out.empty()&&t>=c->write)destroy(c);else if(c->out.empty()&&!c->waiting&&!c->uploading){if(!c->in.empty()&&c->first&&t>=c->first+(long long)cfg.ht){error(c,408,true);refresh(c);}else if(c->in.empty()&&t>=c->idle)destroy(c);}}}return 0;}
